    #[inline]
    pub fn mx_keyword_name_p(n: Str) -> bool {
        (_gt(string_length(n), int_lit(2)) && string_eq_p(substring(n, int_lit(0), int_lit(2)), str_lit!("#:")) && not(char_numeric_p(string_ref(n, int_lit(2)))))
    }

    #[inline]
    pub fn mx_keyword_p(d: kayak_rt::value::Value) -> bool {
        (symbol_p(d) && mx_keyword_name_p(symbol_to_string(kayak_rt::value::unbox::<Symbol>(d))))
    }

    pub fn mx_keyword_to_symbol(d: kayak_rt::value::Value) -> Symbol {
        if symbol_p(d) {
            let n = symbol_to_string(kayak_rt::value::unbox::<Symbol>(d));
            string_to_symbol(substring(n, int_lit(2), string_length(n)))
        } else {
            string_to_symbol(str_lit!(""))
        }
    }

    #[inline]
    pub fn mx_symbol_to_keyword(n: Symbol) -> Symbol {
        string_to_symbol(string_append(str_lit!("#:"), symbol_to_string(n)))
    }

    #[inline]
    pub fn mx_datum_int_p(d: kayak_rt::value::Value) -> bool {
        int_p(d)
    }

    #[inline]
    pub fn mx_symbol_hash(s: Symbol) -> Int {
        symbol_name_hash(s)
    }

    #[inline]
    pub fn mx_symbol_eq_p(a: Symbol, b: Symbol) -> bool {
        symbol_eq_p(a, b)
    }

    #[inline]
    pub fn mx_make_table<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, hash: kayak_rt::Proc1s<'mxp, Symbol, Int>, same: kayak_rt::Proc2s<'mxp, Symbol, Symbol, bool>) -> Array<List<Symbol>> {
        the::<Array<List<Symbol>>>(make_array(int_lit(64), nil::<Symbol>()))
    }

    #[inline]
    pub fn mx_table_bucket(k: Symbol) -> Int {
        modulo(symbol_name_hash(k), int_lit(64))
    }

    pub fn mx_table_has_p(mut b: List<Symbol>, mut k: Symbol) -> bool {
        loop {
            if null_p(b) {
                return false;
            } else if symbol_eq_p(car(b), k) {
                return true;
            } else {
                b = cdr(b);
                continue;
            }
        }
    }

    #[inline]
    pub fn mx_table_ref<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, t: Array<List<Symbol>>, k: Symbol, d: bool) -> bool {
        if mx_table_has_p(array_ref(t, mx_table_bucket(k)), k) {
            true
        } else {
            d
        }
    }

    pub fn mx_table_set_x<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, t: Array<List<Symbol>>, k: Symbol, v: bool) -> () {
        let i = mx_table_bucket(k);
        if v {
            if mx_table_has_p(array_ref(t, i), k) {
                ()
            } else {
                array_set_x(t, i, cons(k, array_ref(t, i)))
            }
        } else {
            error(str_lit!("the expander's table of symbols holds `#t` alone"))
        }
    }

    #[inline]
    pub fn mx_eq_p(a: bool, b: bool) -> bool {
        if a {
            b
        } else {
            not(b)
        }
    }

    #[inline]
    pub fn mx_datum_dotted(xs: List<kayak_rt::value::Value>, tail: kayak_rt::value::Value) -> kayak_rt::value::Value {
        if null_p(xs) {
            tail
        } else {
            the::<kayak_rt::value::Value>(kayak_rt::value::cons(car(xs), mx_datum_dotted(cdr(xs), tail)))
        }
    }

    pub fn mx_parse_nat_from(mut s: Str, mut radix: Int, mut i: Int, mut acc: Int) -> Int {
        loop {
            if _eq(i, string_length(s)) {
                return acc;
            } else {
                let d = _minus(char_to_integer(string_ref(s, i)), int_lit(48));
                if (_gt_eq(d, int_lit(0)) && _lt(d, radix)) {
                    (i, acc) = (_plus(i, int_lit(1)), _plus(_star(acc, radix), d));
                    continue;
                } else {
                    return int_lit(-1);
                }
            }
        }
    }

    #[inline]
    pub fn mx_parse_nat(s: Str, radix: Int) -> Int {
        if _eq(string_length(s), int_lit(0)) {
            int_lit(-1)
        } else {
            mx_parse_nat_from(s, radix, int_lit(0), int_lit(0))
        }
    }

    pub fn mx_phase1_tag_end(mut r: Str, mut i: Int) -> Int {
        loop {
            if _gt_eq(i, string_length(r)) {
                return i;
            } else if char_eq_p(string_ref(r, i), ' ') {
                return i;
            } else {
                i = _plus(i, int_lit(1));
                continue;
            }
        }
    }

    pub fn mx_phase1_key(r: Str) -> Str {
        if (_gt(string_length(r), int_lit(9)) && (string_eq_p(substring(r, int_lit(0), int_lit(9)), str_lit!("%apply 1 ")) || string_eq_p(substring(r, int_lit(0), int_lit(9)), str_lit!("%apply 2 ")))) {
            string_append(substring(r, int_lit(0), int_lit(9)), string_append(str_lit!("0"), substring(r, mx_phase1_tag_end(r, int_lit(9)), string_length(r))))
        } else {
            r
        }
    }

    pub fn mx_phase1_in(mut request: Str, mut xs: kayak_rt::value::Value) -> Str {
        loop {
            if kayak_rt::value::pair_p(xs) {
                let x = kayak_rt::value::car(xs);
                let k = if kayak_rt::value::pair_p(x) {
                    kayak_rt::value::car(x)
                } else {
                    the::<kayak_rt::value::Value>(kayak_rt::value::Value::Nil)
                };
                let v = if kayak_rt::value::pair_p(x) {
                    kayak_rt::value::cdr(x)
                } else {
                    the::<kayak_rt::value::Value>(kayak_rt::value::Value::Nil)
                };
                if string_p(k) {
                    if string_p(v) {
                        if string_eq_p(kayak_rt::value::unbox::<Str>(k), request) {
                            return kayak_rt::value::unbox::<Str>(v);
                        } else {
                            xs = kayak_rt::value::cdr(xs);
                            continue;
                        }
                    } else {
                        xs = kayak_rt::value::cdr(xs);
                        continue;
                    }
                } else {
                    xs = kayak_rt::value::cdr(xs);
                    continue;
                }
            } else {
                return str_lit!("");
            }
        }
    }

    pub fn mx_expand_procedural<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, asked: Str) -> Str {
        let request = mx_phase1_key(asked);
        let a = mx_phase1_in(request, get(maker_st.mx_phase1_given.get().unwrap()));
        if not(string_eq_p(a, str_lit!(""))) {
            a
        } else {
            let b = (get(maker_st.mx_phase1_asker.get().unwrap())).call(request);
            if string_eq_p(b, str_lit!("")) {
                str_lit!("!a procedural macro's transformer, run as the program is read: not yet here")
            } else {
                set(maker_st.mx_phase1_given.get().unwrap(), the::<kayak_rt::value::Value>(kayak_rt::value::cons(the::<kayak_rt::value::Value>(kayak_rt::value::cons(the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(request)), the::<kayak_rt::value::Value>(kayak_rt::value::ToValue::to_value(b)))), get(maker_st.mx_phase1_given.get().unwrap()))));
                b
            }
        }
    }

    #[inline]
    pub fn mx_call_procedural(style: Int, code: Str, d: kayak_rt::value::Value, x: Str, forms: List<Str>) -> kayak_rt::Sum {
        kayak_rt::sum_tagged::<()>(kayak_rt::tag_lit!("apart"), ())
    }

    pub fn mx_limit(name: Str) -> Str {
        if string_eq_p(name, str_lit!("USES")) {
            str_lit!("=10000")
        } else if string_eq_p(name, str_lit!("DEPTH")) {
            str_lit!("=1000")
        } else if string_eq_p(name, str_lit!("RECHECK")) {
            str_lit!("=0")
        } else if string_eq_p(name, str_lit!("CONTRACTS")) {
            str_lit!("=1")
        } else {
            string_append(str_lit!("!no limit of macro expansion is named `"), string_append(name, str_lit!("`")))
        }
    }

    pub fn mx_parse_number(s: Str, radix: Int) -> List<kayak_rt::value::Value> {
        let neg = (_gt(string_length(s), int_lit(1)) && char_eq_p(string_ref(s, int_lit(0)), '-'));
        let digits = if (neg || (_gt(string_length(s), int_lit(1)) && char_eq_p(string_ref(s, int_lit(0)), '+'))) {
            substring(s, int_lit(1), string_length(s))
        } else {
            s
        };
        let n = mx_parse_nat(digits, radix);
        if _lt(n, int_lit(0)) {
            nil::<kayak_rt::value::Value>()
        } else {
            kayak_rt::heap_cons(the::<kayak_rt::value::Value>(if neg {
                kayak_rt::value::ToValue::to_value(_minus(int_lit(0), n))
            } else {
                kayak_rt::value::ToValue::to_value(n)
            }), kayak_rt::nil())
        }
    }

