    pub fn fill_rules<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mode: Int, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, root: Int) -> Result<(), Unwind> {
        let items = rules_items(s);
        if not(_eq(mode, int_lit(1))) {
            Ok(())
        } else if syn_symbol_p(s) {
            with_many(mxp, maker_st, at);
            if ellipsis_p(s) {
                Ok(match fail_at(mxp, maker_st, mx_fail, maker_st.rules_dots.get().unwrap(), s)? {})
            } else if rules_word_p(mxp, maker_st, mx_fail, syn_symbol(mxp, maker_st, s)?)? {
                Ok(())
            } else {
                Ok(with_kids(mxp, maker_st, at, k_ref(syn_symbol(mxp, maker_st, s)?, false, int_lit(4))))
            }
        } else if syn_nil_p(s) {
            with_many(mxp, maker_st, at);
            Ok(with_kids(mxp, maker_st, at, k_nil()))
        } else if null_p(items) {
            Ok(with_many(mxp, maker_st, at))
        } else if (_eq(len(items), int_lit(2)) && proper_p(s) && ellipsis_p(car(items)) && ellipsis_p(nth(items, int_lit(1)))) {
            Ok(with_many(mxp, maker_st, at))
        } else if ellipsis_p(car(items)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, maker_st.rules_escape.get().unwrap(), s)? {})
        } else if any_ellipsis_p(items) {
            Ok(match fail_at(mxp, maker_st, mx_fail, maker_st.rules_dots.get().unwrap(), s)? {})
        } else if (syn_symbol_p(car(items)) && string_eq_p(syn_name(car(items)), str_lit!("quote"))) {
            with_many(mxp, maker_st, at);
            Ok(fill(mxp, maker_st, mx_fail, mode, ps, at, s_data(), s, root)?)
        } else if rules_define_p(s) {
            with_many(mxp, maker_st, at);
            Ok(fill(mxp, maker_st, mx_fail, mode, ps, at, rules_define_sig(), s, root)?)
        } else {
            with_many(mxp, maker_st, at);
            Ok(fill(mxp, maker_st, mx_fail, mode, ps, at, s_pair(s_rules(), s_rules()), s, root)?)
        }
    }

