    pub fn template_form<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, defn: bool) -> Result<(), Unwind> {
        let parts = split(s);
        let hd = car(parts);
        let head = if (syn_symbol_p(hd) && not(pvar_p(syn_symbol(mxp, maker_st, hd)?, ps))) {
            syn_name(hd)
        } else {
            str_lit!("")
        };
        let kernel = kernel_sigs(mxp, maker_st, mx_fail)?;
        let defs = kernel_definitions(mxp, maker_st, mx_fail)?;
        let r#macro = (not(string_eq_p(head, str_lit!(""))) && macro_p(mxp, maker_st, syn_symbol(mxp, maker_st, hd)?));
        if (get(maker_st.heads_on.get().unwrap()) && syn_symbol_p(hd) && unknown_head_p(mxp, maker_st, mx_fail, syn_symbol(mxp, maker_st, hd)?, ps)?) {
            Ok(pending_form(mxp, maker_st, mx_fail, ps, at, s, defn)?)
        } else if (r#macro && _eq(makes(mxp, maker_st, syn_symbol(mxp, maker_st, hd)?), int_lit(3))) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(head, string_append(str_lit!("` is a procedural macro, whose binding structure "), str_lit!("no signature says: not in a template")))), s)? {})
        } else if defn {
            Ok(defn_form(mxp, maker_st, mx_fail, ps, at, s, int_lit(1))?)
        } else if constructs_p(mxp, maker_st, hd, ps)? {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(1), ps, car(sig_of(kayak_rt::sym_lit!("%construct"), kernel)), s, int_lit(-1), node_path(mxp, maker_st, at))?)))
        } else if (r#macro && makes_defns_p(mxp, maker_st, syn_symbol(mxp, maker_st, hd)?)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(head, string_append(str_lit!("` makes definitions, which are made at the top "), str_lit!("level, not where an expression is")))), s)? {})
        } else if (r#macro && makes_desc_p(mxp, maker_st, syn_symbol(mxp, maker_st, hd)?)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(head, str_lit!("` makes a description, not an expression"))), s)? {})
        } else if (not(string_eq_p(head, str_lit!(""))) && not(null_p(sig_of(string_to_symbol(head), defs))) && null_p(sig_of(string_to_symbol(head), kernel))) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(head, string_append(str_lit!("` makes a definition, made at the top level by a "), str_lit!("macro that makes definitions, not where an expression is")))), s)? {})
        } else if string_eq_p(head, str_lit!("with")) {
            if standard_with_p(s) {
                Ok(())
            } else if (_eq(len(proper_items(s)), int_lit(3)) && syn_symbol_p(nth(proper_items(s), int_lit(1))) && syn_symbol_p(nth(proper_items(s), int_lit(2)))) {
                let x = align(mxp, maker_st, mx_fail, int_lit(1), ps, s_pair(s_id(), s_pair(s_data(), s_nil())), nth(parts, int_lit(1)), int_lit(-1), path_plus(mxp, maker_st, node_path(mxp, maker_st, at), false))?;
                {
                    let tagcase_ = node_kids(mxp, maker_st, x);
                    if made__load__0__expander_kc::MxNodesKids::__is_KPair(tagcase_) {
                        let (m, y,) = made__load__0__expander_kc::MxNodesKids::__KPair(tagcase_);
                        let tagcase_ = node_kids(mxp, maker_st, m);
                        if made__load__0__expander_kc::MxNodesKids::__is_KRef(tagcase_) {
                            let (n, d, f,) = made__load__0__expander_kc::MxNodesKids::__KRef(tagcase_);
                            with_kids(mxp, maker_st, m, k_ref(n, d, int_lit(3)))
                        } else {
                            let z = tagcase_;
                            ()
                        }
                    } else {
                        let y = tagcase_;
                        ()
                    }
                };
                Ok(with_kids(mxp, maker_st, at, k_form(x)))
            } else {
                Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("a template's `with` is `(with module name)`, the "), string_append(str_lit!("value `name` of the module, or `(with #%fx name)` or "), string_append(str_lit!("`(with #%toplevel name)` (one opening a module over "), str_lit!("a body waits for scopes of a module's names)")))), s)? {})
            }
        } else if r#macro {
            Ok(operands_as(mxp, maker_st, mx_fail, int_lit(1), ps, at, car(macro_of(syn_symbol(mxp, maker_st, hd)?, get(maker_st.defined.get().unwrap()))).0, nth(parts, int_lit(1)))?)
        } else if (not(string_eq_p(head, str_lit!(""))) && not(string_eq_p(substring(head, int_lit(0), int_lit(1)), str_lit!("%"))) && not(null_p(sig_of(string_to_symbol(head), kernel)))) {
            Ok(operands(mxp, maker_st, mx_fail, ps, at, car(sig_of(string_to_symbol(head), kernel)), nth(parts, int_lit(1)))?)
        } else if (not(string_eq_p(head, str_lit!(""))) && {
            let sig = sig_of(string_to_symbol(head), scope_sigs(mxp, maker_st, mx_fail)?);
            (not(null_p(sig)) && binds_nothing_p(car(sig)))
        }) {
            Ok(operands(mxp, maker_st, mx_fail, ps, at, car(sig_of(string_to_symbol(head), scope_sigs(mxp, maker_st, mx_fail)?)), nth(parts, int_lit(1)))?)
        } else if (not(string_eq_p(head, str_lit!(""))) && reserved_p(mxp, maker_st, head)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("the prototype does not know `"), string_append(head, string_append(str_lit!("`'s binding "), str_lit!("structure: not yet in a template")))), s)? {})
        } else {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(1), ps, car(sig_of(kayak_rt::sym_lit!("%app"), kernel)), s, int_lit(-1), node_path(mxp, maker_st, at))?)))
        }
    }

    pub fn pending_form<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, defn: bool) -> Result<(), Unwind> {
        let (read, n) = (head_read(mxp, maker_st, s), syn_name(car(split(s))));
        pending_x(mxp, maker_st, at, defn);
        if not(null_p(read)) {
            let t = car(syntax_sig_read(mxp, maker_st, car(read)));
            let made = t.1;
            if (not(defn) && _eq(made, int_lit(1))) {
                Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(n, string_append(str_lit!("` makes definitions, which are made "), string_append(str_lit!("at the top level, not where an expression "), str_lit!("is"))))), s)? {})
            } else if (not(defn) && _eq(made, int_lit(2))) {
                Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(n, string_append(str_lit!("` makes a description, not an "), str_lit!("expression")))), s)? {})
            } else if (defn && _eq(made, int_lit(2))) {
                Ok(not_definition(mxp, maker_st, mx_fail, s, string_append(str_lit!("them by a macro that makes "), str_lit!("definitions, not a description's")))?)
            } else if (defn && _eq(made, int_lit(0))) {
                Ok(not_definition(mxp, maker_st, mx_fail, s, string_append(str_lit!("them by a macro that makes "), str_lit!("definitions, not an expression's")))?)
            } else {
                Ok(operands(mxp, maker_st, mx_fail, ps, at, t.0, nth(split(s), int_lit(1)))?)
            }
        } else if defn {
            Ok(with_export(mxp, maker_st, at, bind_rib(nil::<Product_11_12<List<bool>, Int>>()), at))
        } else {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(1), ps, car(sig_of(kayak_rt::sym_lit!("%app"), kernel_sigs(mxp, maker_st, mx_fail)?)), s, int_lit(-1), node_path(mxp, maker_st, at))?)))
        }
    }

    pub fn program_expr<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>) -> Result<(), Unwind> {
        if syn_symbol_p(s) {
            if {
                let n = syn_symbol(mxp, maker_st, s)?;
                (symbol_eq_p(n, string_to_symbol(str_lit!("#t"))) || symbol_eq_p(n, string_to_symbol(str_lit!("#f"))) || symbol_eq_p(n, string_to_symbol(str_lit!("#u"))))
            } {
                Ok(())
            } else {
                Ok(with_kids(mxp, maker_st, at, k_ref(syn_symbol(mxp, maker_st, s)?, false, int_lit(0))))
            }
        } else if syn_nil_p(s) {
            Ok(match fail_at(mxp, maker_st, mx_fail, str_lit!("`()` is not an expression"), s)? {})
        } else if not(null_p(split(s))) {
            Ok(mx_align_form(mxp, maker_st, mx_fail, ps, at, s, false)?)
        } else {
            Ok(())
        }
    }

    pub fn program_form<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, defn: bool) -> Result<(), Unwind> {
        let parts = split(s);
        let hd = car(parts);
        let n = if syn_symbol_p(hd) {
            syn_symbol(mxp, maker_st, hd)?
        } else {
            string_to_symbol(str_lit!(""))
        };
        let kernel = kernel_sigs(mxp, maker_st, mx_fail)?;
        let sforms = scope_sigs(mxp, maker_st, mx_fail)?;
        let defs = kernel_definitions(mxp, maker_st, mx_fail)?;
        let sdefs = scope_definitions(mxp, maker_st, mx_fail)?;
        if (get(maker_st.scoped_on.get().unwrap()) && macro_p(mxp, maker_st, n) && scoped_read_x(mxp, maker_st, mx_fail, ps, at, s, defn)?) {
            Ok(())
        } else if (macro_p(mxp, maker_st, n) && _eq(makes(mxp, maker_st, n), int_lit(3))) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(symbol_to_string(n), string_append(str_lit!("` is a procedural macro, whose "), str_lit!("binding structure no signature says: not in a template")))), s)? {})
        } else if defn {
            Ok(defn_form(mxp, maker_st, mx_fail, ps, at, s, int_lit(3))?)
        } else if syn_keyword_p(hd) {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(3), ps, car(sig_of(kayak_rt::sym_lit!("%construct"), kernel)), s, int_lit(-1), node_path(mxp, maker_st, at))?)))
        } else if (symbol_eq_p(n, kayak_rt::sym_lit!("quasiquote")) && _eq(len(proper_items(s)), int_lit(2))) {
            Ok(with_kids(mxp, maker_st, at, k_desc(unquoted(mxp, maker_st, mx_fail, ps, nth(proper_items(s), int_lit(1)), path_plus(mxp, maker_st, path_plus(mxp, maker_st, node_path(mxp, maker_st, at), false), true), int_lit(1), nil::<Int>())?)))
        } else if (symbol_eq_p(n, kayak_rt::sym_lit!("with")) && standard_with_p(s)) {
            Ok(())
        } else if (macro_p(mxp, maker_st, n) && makes_defns_p(mxp, maker_st, n)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(symbol_to_string(n), string_append(str_lit!("` makes definitions, which are made "), str_lit!("at the top level, not where an expression is")))), s)? {})
        } else if (macro_p(mxp, maker_st, n) && makes_desc_p(mxp, maker_st, n)) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(symbol_to_string(n), string_append(str_lit!("` makes a description, not an "), str_lit!("expression")))), s)? {})
        } else if macro_p(mxp, maker_st, n) {
            Ok(operands_as(mxp, maker_st, mx_fail, int_lit(3), ps, at, car(macro_of(n, get(maker_st.defined.get().unwrap()))).0, nth(parts, int_lit(1)))?)
        } else if not(null_p(sig_of(n, sforms))) {
            Ok(operands_as(mxp, maker_st, mx_fail, int_lit(3), ps, at, car(sig_of(n, sforms)), nth(parts, int_lit(1)))?)
        } else if (not(null_p(sig_of(n, kernel))) && not(mx_syntax_name_in_p(n, percent_named(mxp, maker_st, kernel)))) {
            Ok(operands_as(mxp, maker_st, mx_fail, int_lit(3), ps, at, car(sig_of(n, kernel)), nth(parts, int_lit(1)))?)
        } else {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(3), ps, car(sig_of(kayak_rt::sym_lit!("%app"), kernel)), s, int_lit(-1), node_path(mxp, maker_st, at))?)))
        }
    }

    pub fn scoped_read_x<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, defn: bool) -> Result<bool, Unwind> {
        let app = {
            pending_x(mxp, maker_st, at, defn);
            addr_in_p(node_path(mxp, maker_st, at), get(maker_st.scoped_apps.get().unwrap()))
        };
        if (app && defn) {
            not_definition(mxp, maker_st, mx_fail, s, maker_st.definitions_said.get().unwrap())?;
            Ok(true)
        } else if app {
            let app_sig = car(sig_of(kayak_rt::sym_lit!("%app"), kernel_sigs(mxp, maker_st, mx_fail)?));
            with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(3), ps, app_sig, s, int_lit(-1), node_path(mxp, maker_st, at))?));
            Ok(true)
        } else if get(maker_st.scoped_whole.get().unwrap()) {
            use_whole_x(mxp, maker_st, at, defn);
            Ok(true)
        } else {
            Ok(false)
        }
    }

    pub fn operands_as<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mode: Int, ps: Pvars, at: Int, sig: kayak_rt::data::DataAt<'static, Sty>, rest: kayak_rt::data::DataAt<'static, Syn>) -> Result<(), Unwind> {
        Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, mode, ps, sig, rest, int_lit(-1), path_plus(mxp, maker_st, node_path(mxp, maker_st, at), false))?)))
    }

    #[inline]
    pub fn unquoted<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, s: kayak_rt::data::DataAt<'static, Syn>, path: Addr, depth: Int, mx_nodes_kids: List<Int>) -> Result<List<Int>, Unwind> {
        Ok(the::<List<Int>>(reverse(unquoted_onto(mxp, maker_st, mx_fail, ps, s, path, depth, mx_nodes_kids)?)))
    }

    pub fn unquoted_onto<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut s: kayak_rt::data::DataAt<'static, Syn>, mut path: Addr, mut depth: Int, mut mx_nodes_kids: List<Int>) -> Result<List<Int>, Unwind> {
        loop {
            let tagcase_ = s;
            if made__load__0__expander_kc::Syn::__is_MxEagerReaderTypesLst(tagcase_) {
                let (items, d, a, b, x,) = made__load__0__expander_kc::Syn::__MxEagerReaderTypesLst(tagcase_);
                let (head, inner) = (if (not(null_p(items)) && syn_symbol_p(car(items))) {
                    syn_name(car(items))
                } else {
                    str_lit!("")
                }, path_plus(mxp, maker_st, path_plus(mxp, maker_st, path, false), true));
                if (_eq(len(items), int_lit(2)) && _eq(depth, int_lit(1)) && (string_eq_p(head, str_lit!("unquote")) || string_eq_p(head, str_lit!("unquote-splicing")))) {
                    return Ok(cons(align(mxp, maker_st, mx_fail, int_lit(3), ps, s_expr(), nth(items, int_lit(1)), int_lit(-1), inner)?, mx_nodes_kids));
                } else if (_eq(len(items), int_lit(2)) && (string_eq_p(head, str_lit!("unquote")) || string_eq_p(head, str_lit!("unquote-splicing")))) {
                    (s, path, depth) = (nth(items, int_lit(1)), inner, _minus(depth, int_lit(1)));
                    continue;
                } else if (_eq(len(items), int_lit(2)) && string_eq_p(head, str_lit!("quasiquote"))) {
                    (s, path, depth) = (nth(items, int_lit(1)), inner, _plus(depth, int_lit(1)));
                    continue;
                } else {
                    return Ok(unquoted_items(mxp, maker_st, mx_fail, ps, items, path, depth, mx_nodes_kids)?);
                }
            } else if made__load__0__expander_kc::Syn::__is_Dotted(tagcase_) {
                let (items, tail, d, a, b, x,) = made__load__0__expander_kc::Syn::__Dotted(tagcase_);
                (s, path, mx_nodes_kids) = (tail, mx_align_falses(mxp, maker_st, path, len(items)), unquoted_items(mxp, maker_st, mx_fail, ps, items, path, depth, mx_nodes_kids)?);
                continue;
            } else if made__load__0__expander_kc::Syn::__is_Vec(tagcase_) {
                let (items, d, a, b, x,) = made__load__0__expander_kc::Syn::__Vec(tagcase_);
                if any_unquotes_p(items) {
                    set(maker_st.unplaced.get().unwrap(), symbols_onto(mxp, maker_st, items, get(maker_st.unplaced.get().unwrap()))?)
                } else {
                    ()
                };
                return Ok(mx_nodes_kids);
            } else {
                let y = tagcase_;
                return Ok(mx_nodes_kids);
            }
        }
    }

    pub fn unquoted_items<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut items: SynsA, mut path: Addr, mut depth: Int, mut mx_nodes_kids: List<Int>) -> Result<List<Int>, Unwind> {
        loop {
            if null_p(items) {
                return Ok(mx_nodes_kids);
            } else {
                (items, path, mx_nodes_kids) = (cdr(items), path_plus(mxp, maker_st, path, false), unquoted_onto(mxp, maker_st, mx_fail, ps, car(items), path_plus(mxp, maker_st, path, true), depth, mx_nodes_kids)?);
                continue;
            }
        }
    }

    pub fn defn_form<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, mode: Int) -> Result<(), Unwind> {
        let parts = split(s);
        let hd = car(parts);
        let items = proper_items(s);
        let program = _eq(mode, int_lit(3));
        let n = if (syn_symbol_p(hd) && not(pvar_p(syn_symbol(mxp, maker_st, hd)?, ps))) {
            syn_symbol(mxp, maker_st, hd)?
        } else {
            string_to_symbol(str_lit!(""))
        };
        let defs = kernel_definitions(mxp, maker_st, mx_fail)?;
        let sdefs = if program {
            scope_definitions(mxp, maker_st, mx_fail)?
        } else {
            nil::<Product_11_12<Symbol, kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Sty>>>()
        };
        let r#macro = macro_p(mxp, maker_st, n);
        if (program && symbol_eq_p(n, kayak_rt::sym_lit!("module-parameters")) && _eq(len(items), int_lit(2))) {
            Ok(operands_as(mxp, maker_st, mx_fail, int_lit(3), ps, at, parameters_sig(mxp, maker_st, nth(items, int_lit(1)))?, nth(parts, int_lit(1)))?)
        } else if (symbol_eq_p(n, kayak_rt::sym_lit!("define-syntax")) && proper_p(s) && (_eq(len(items), int_lit(3)) || _eq(len(items), int_lit(4)))) {
            let t = nth(items, _minus(len(items), int_lit(1)));
            let ts = proper_items(t);
            if (not(program) && not((pair_p(ts) && syn_symbol_p(car(ts)) && string_eq_p(syn_name(car(ts)), str_lit!("syntax-rules"))))) {
                Ok(match fail_at(mxp, maker_st, mx_fail, maker_st.rules_procedural.get().unwrap(), t)? {})
            } else {
                Ok(operands_as(mxp, maker_st, mx_fail, mode, ps, at, define_syntax_sig(_eq(len(items), int_lit(4))), nth(parts, int_lit(1)))?)
            }
        } else if (not(program) && symbol_eq_p(n, kayak_rt::sym_lit!("define-generative")) && _eq(len(items), int_lit(3))) {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("a template's `define-generative` names its "), str_lit!("conversions, `#:seal` and `#:unseal`")), s)? {})
        } else if (r#macro && makes_defns_p(mxp, maker_st, n)) {
            Ok(operands_as(mxp, maker_st, mx_fail, mode, ps, at, car(macro_of(n, get(maker_st.defined.get().unwrap()))).0, nth(parts, int_lit(1)))?)
        } else if (r#macro && makes_desc_p(mxp, maker_st, n)) {
            Ok(not_definition(mxp, maker_st, mx_fail, s, str_lit!("them by a macro that makes definitions, not a description's"))?)
        } else if r#macro {
            Ok(not_definition(mxp, maker_st, mx_fail, s, str_lit!("them by a macro that makes definitions, not an expression's"))?)
        } else if not(null_p(sig_of(n, defs))) {
            Ok(operands_as(mxp, maker_st, mx_fail, mode, ps, at, car(sig_of(n, defs)), nth(parts, int_lit(1)))?)
        } else if not(null_p(sig_of(n, sdefs))) {
            Ok(operands_as(mxp, maker_st, mx_fail, mode, ps, at, car(sig_of(n, sdefs)), nth(parts, int_lit(1)))?)
        } else {
            Ok(not_definition(mxp, maker_st, mx_fail, s, maker_st.definitions_said.get().unwrap())?)
        }
    }

    pub fn operands<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, sig: kayak_rt::data::DataAt<'static, Sty>, rest: kayak_rt::data::DataAt<'static, Syn>) -> Result<(), Unwind> {
        Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(1), ps, sig, rest, int_lit(-1), path_plus(mxp, maker_st, node_path(mxp, maker_st, at), false))?)))
    }

    pub fn desc<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>) -> Result<(), Unwind> {
        let tagcase_ = s;
        if made__load__0__expander_kc::Syn::__is_MxEagerReaderTypesLst(tagcase_) {
            let (items, d, a, b, x,) = made__load__0__expander_kc::Syn::__MxEagerReaderTypesLst(tagcase_);
            if null_p(items) {
                Ok(())
            } else {
                Ok(desc_list(mxp, maker_st, mx_fail, ps, at, s, items)?)
            }
        } else if made__load__0__expander_kc::Syn::__is_Dotted(tagcase_) {
            let (items, tail, d, a, b, x,) = made__load__0__expander_kc::Syn::__Dotted(tagcase_);
            Ok(match fail_at(mxp, maker_st, mx_fail, str_lit!("a description is a list, not a dotted one"), s)? {})
        } else {
            let y = tagcase_;
            if syn_symbol_p(s) {
                let n = syn_symbol(mxp, maker_st, s)?;
                Ok(with_kids(mxp, maker_st, at, if pvar_p(n, ps) {
                    k_pvar(n)
                } else if desc_word_p(mxp, maker_st, syn_name(s), false) {
                    k_other()
                } else {
                    k_ref(n, true, int_lit(1))
                }))
            } else {
                Ok(())
            }
        }
    }

    pub fn desc_list<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, items: SynsA) -> Result<(), Unwind> {
        if (syn_symbol_p(car(items)) && not(pvar_p(syn_symbol(mxp, maker_st, car(items))?, ps)) && macro_p(mxp, maker_st, syn_symbol(mxp, maker_st, car(items))?)) {
            Ok(desc_use(mxp, maker_st, mx_fail, ps, at, s, syn_symbol(mxp, maker_st, car(items))?)?)
        } else {
            Ok(desc_items(mxp, maker_st, mx_fail, ps, at, s, items)?)
        }
    }

    pub fn desc_use<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, n: Symbol) -> Result<(), Unwind> {
        if (get(maker_st.scoped_on.get().unwrap()) && get(maker_st.scoped_whole.get().unwrap()) && makes_desc_p(mxp, maker_st, n)) {
            pending_x(mxp, maker_st, at, false);
            Ok(use_whole_x(mxp, maker_st, at, false))
        } else if makes_desc_p(mxp, maker_st, n) {
            Ok(with_kids(mxp, maker_st, at, k_form(align(mxp, maker_st, mx_fail, int_lit(1), ps, car(macro_of(n, get(maker_st.defined.get().unwrap()))).0, nth(split(s), int_lit(1)), int_lit(-1), path_plus(mxp, maker_st, node_path(mxp, maker_st, at), false))?)))
        } else {
            Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`"), string_append(symbol_to_string(n), string_append(str_lit!("` makes "), string_append(if makes_defns_p(mxp, maker_st, n) {
                str_lit!("definitions")
            } else {
                str_lit!("an expression")
            }, str_lit!(", not a description"))))), s)? {})
        }
    }

    pub fn desc_items<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, items: SynsA) -> Result<(), Unwind> {
        let mx_nodes_kids = desc_kids(mxp, maker_st, at, items);
        let h = car(items);
        let head = if (syn_symbol_p(h) && not(pvar_p(syn_symbol(mxp, maker_st, h)?, ps))) {
            syn_name(h)
        } else {
            str_lit!("")
        };
        if ((string_eq_p(head, str_lit!("poly")) || string_eq_p(head, str_lit!("dlambda"))) && get(maker_st.program_walk.get().unwrap()) && _gt(len(items), int_lit(3))) {
            Ok(desc_each_scoped(mxp, maker_st, mx_fail, ps, cdr(cdr(mx_nodes_kids)), cdr(cdr(items)), desc_binders(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(1)), nth(items, int_lit(1)))?)?)
        } else if (string_eq_p(head, str_lit!("poly")) || string_eq_p(head, str_lit!("dlambda"))) {
            if _eq(len(items), int_lit(3)) {
                Ok(desc_scoped(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(2)), nth(items, int_lit(2)), desc_binders(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(1)), nth(items, int_lit(1)))?)?)
            } else {
                Ok(match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("`("), string_append(head, str_lit!(" ((name kind) …) description)`"))), s)? {})
            }
        } else if string_eq_p(head, str_lit!("mu")) {
            if _eq(len(items), int_lit(3)) {
                Ok(desc_scoped(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(2)), nth(items, int_lit(2)), kayak_rt::cons(desc_binder(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(1)), nth(items, int_lit(1)))?, kayak_rt::nil()))?)
            } else {
                Ok(match fail_at(mxp, maker_st, mx_fail, str_lit!("`(mu name type)`"), s)? {})
            }
        } else if string_eq_p(head, str_lit!("dletrec")) {
            if _eq(len(items), int_lit(3)) {
                Ok(desc_dletrec(mxp, maker_st, mx_fail, ps, mx_nodes_kids, items)?)
            } else {
                Ok(match fail_at(mxp, maker_st, mx_fail, str_lit!("`(dletrec ((name description) …) description)`"), s)? {})
            }
        } else if (string_eq_p(head, str_lit!("productof")) || string_eq_p(head, str_lit!("sumof"))) {
            Ok(desc_fields(mxp, maker_st, mx_fail, ps, cdr(mx_nodes_kids), cdr(items))?)
        } else if (string_eq_p(head, str_lit!("restrict")) && _gt_eq(len(items), int_lit(2))) {
            Ok(desc(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(1)), nth(items, int_lit(1)))?)
        } else if string_eq_p(head, str_lit!("io")) {
            Ok(())
        } else if string_eq_p(head, str_lit!("globals")) {
            Ok(desc_values(mxp, maker_st, mx_fail, ps, cdr(mx_nodes_kids), int_lit(2))?)
        } else if string_eq_p(head, str_lit!("select")) {
            if null_p(cdr(mx_nodes_kids)) {
                Ok(())
            } else {
                Ok(select_path(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(1)), nth(items, int_lit(1)))?)
            }
        } else if (get(maker_st.program_walk.get().unwrap()) && (string_eq_p(head, str_lit!("load-moduleof")) || string_eq_p(head, str_lit!("load-input-moduleof")))) {
            Ok(set(maker_st.unplaced.get().unwrap(), symbols_onto(mxp, maker_st, cdr(cdr(items)), get(maker_st.unplaced.get().unwrap()))?))
        } else if string_eq_p(head, str_lit!("moduleof")) {
            Ok(desc_members(mxp, maker_st, mx_fail, ps, cdr(mx_nodes_kids), cdr(items), nil::<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Atm>>(), not(get(maker_st.program_walk.get().unwrap())))?)
        } else if (string_eq_p(head, str_lit!("subr")) || string_eq_p(head, str_lit!("->")) || string_eq_p(head, str_lit!("->*"))) {
            Ok(desc_subr(mxp, maker_st, mx_fail, ps, s, items, mx_nodes_kids)?)
        } else if (not(string_eq_p(head, str_lit!(""))) && desc_word_p(mxp, maker_st, head, true)) {
            Ok(desc_each(mxp, maker_st, mx_fail, ps, cdr(mx_nodes_kids), cdr(items))?)
        } else {
            Ok(desc_each(mxp, maker_st, mx_fail, ps, mx_nodes_kids, items)?)
        }
    }

    pub fn desc_each<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ks: List<Int>, mut xs: SynsA) -> Result<(), Unwind> {
        loop {
            if (null_p(xs) || null_p(ks)) {
                return Ok(());
            } else {
                desc(mxp, maker_st, mx_fail, ps, car(ks), car(xs))?;
                (ks, xs) = (cdr(ks), cdr(xs));
                continue;
            }
        }
    }

    #[inline]
    pub fn desc_scoped<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, s: kayak_rt::data::DataAt<'static, Syn>, r#as: Atms) -> Result<(), Unwind> {
        with_import(mxp, maker_st, at, bind_direct(r#as), at);
        Ok(desc(mxp, maker_st, mx_fail, ps, at, s)?)
    }

    #[inline]
    pub fn desc_binders<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, at: Int, bs: kayak_rt::data::DataAt<'static, Syn>) -> Result<Atms, Unwind> {
        let entries = proper_items(bs);
        Ok(desc_binders_from(mxp, maker_st, mx_fail, ps, desc_kids(mxp, maker_st, at, entries), entries, nil::<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Atm>>())?)
    }

    pub fn desc_binders_from<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ks: List<Int>, mut es: SynsA, mut out: Atms) -> Result<Atms, Unwind> {
        loop {
            if (null_p(es) || null_p(ks)) {
                return Ok(out);
            } else {
                let parts = proper_items(car(es));
                let n = len(parts);
                if (_eq(n, int_lit(2)) || _eq(n, int_lit(3))) {
                    let p = desc_kids(mxp, maker_st, car(ks), parts);
                    let a = desc_binder(mxp, maker_st, mx_fail, ps, car(p), car(parts))?;
                    if _eq(n, int_lit(3)) {
                        desc_scoped(mxp, maker_st, mx_fail, ps, kid(p, int_lit(2)), nth(parts, int_lit(2)), out)?
                    } else {
                        ()
                    };
                    (ks, es, out) = (cdr(ks), cdr(es), append(out, the::<Atms>(kayak_rt::cons(a, kayak_rt::nil()))));
                    continue;
                } else {
                    match fail_at(mxp, maker_st, mx_fail, str_lit!("a binder is `(name kind)`"), car(es))? {};
                    return Ok(out);
                }
            }
        }
    }

    pub fn desc_dletrec<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, ps: Pvars, mx_nodes_kids: List<Int>, items: SynsA) -> Result<(), Unwind> {
        let entries = proper_items(nth(items, int_lit(1)));
        let parts = dletrec_parts(mxp, maker_st, mx_fail, ps, desc_kids(mxp, maker_st, kid(mx_nodes_kids, int_lit(1)), entries), entries)?;
        let r#as = dparts_atms(parts);
        dparts_each(mxp, maker_st, mx_fail, ps, parts, r#as)?;
        Ok(desc_scoped(mxp, maker_st, mx_fail, ps, kid(mx_nodes_kids, int_lit(2)), nth(items, int_lit(2)), r#as)?)
    }

    pub fn dparts_each<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ds: Dparts, mut r#as: Atms) -> Result<(), Unwind> {
        loop {
            if null_p(ds) {
                return Ok(());
            } else {
                desc_scoped(mxp, maker_st, mx_fail, ps, car(ds).1, car(ds).2, r#as)?;
                ds = cdr(ds);
                continue;
            }
        }
    }

    pub fn desc_fields<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ks: List<Int>, mut fs: SynsA) -> Result<(), Unwind> {
        loop {
            if (null_p(fs) || null_p(ks)) {
                return Ok(());
            } else {
                let parts = proper_items(car(fs));
                if _eq(len(parts), int_lit(2)) {
                    let p = desc_kids(mxp, maker_st, car(ks), parts);
                    if (syn_symbol_p(car(parts)) && pvar_p(syn_symbol(mxp, maker_st, car(parts))?, ps)) {
                        with_core(mxp, maker_st, car(p), s_label());
                        with_kids(mxp, maker_st, car(p), k_pvar(syn_symbol(mxp, maker_st, car(parts))?))
                    } else {
                        ()
                    };
                    desc(mxp, maker_st, mx_fail, ps, kid(p, int_lit(1)), nth(parts, int_lit(1)))?;
                    (ks, fs) = (cdr(ks), cdr(fs));
                    continue;
                } else {
                    if get(maker_st.program_walk.get().unwrap()) {
                        desc(mxp, maker_st, mx_fail, ps, car(ks), car(fs))?;
                        (ks, fs) = (cdr(ks), cdr(fs));
                        continue;
                    } else {
                        return Ok(match fail_at(mxp, maker_st, mx_fail, str_lit!("`(label type)`"), car(fs))? {});
                    }
                }
            }
        }
    }

    pub fn desc_each_scoped<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ks: List<Int>, mut xs: SynsA, mut r#as: Atms) -> Result<(), Unwind> {
        loop {
            if (null_p(xs) || null_p(ks)) {
                return Ok(());
            } else {
                desc_scoped(mxp, maker_st, mx_fail, ps, car(ks), car(xs), r#as)?;
                (ks, xs) = (cdr(ks), cdr(xs));
                continue;
            }
        }
    }

    pub fn desc_members<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, mut ps: Pvars, mut ks: List<Int>, mut ms: SynsA, mut r#as: Atms, mut template: bool) -> Result<(), Unwind> {
        loop {
            if (null_p(ms) || null_p(ks)) {
                return Ok(());
            } else {
                let parts = proper_items(car(ms));
                let word = if (not(null_p(parts)) && syn_symbol_p(car(parts))) {
                    syn_name(car(parts))
                } else {
                    str_lit!("")
                };
                if _lt(len(parts), int_lit(2)) {
                    desc(mxp, maker_st, mx_fail, ps, car(ks), car(ms))?;
                    (ks, ms) = (cdr(ks), cdr(ms));
                    continue;
                } else {
                    let p = desc_kids(mxp, maker_st, car(ks), parts);
                    let n = nth(parts, int_lit(1));
                    let binds = (string_eq_p(word, str_lit!("abs")) || string_eq_p(word, str_lit!("desc")));
                    let kw = syn_keyword_p(n);
                    let apart = (binds && kw && _eq(len(parts), int_lit(4)) && syn_symbol_p(nth(parts, int_lit(2))));
                    let given = (syn_symbol_p(n) && pvar_p(syn_symbol(mxp, maker_st, n)?, ps));
                    if (not(template) || kw || given) {
                        ()
                    } else if not(syn_symbol_p(n)) {
                        match fail_at(mxp, maker_st, mx_fail, str_lit!("a list of names in a template's `moduleof`: not yet"), n)? {}
                    } else if binds {
                        match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("a template's `abs` or `desc` writes "), string_append(str_lit!("its label as a keyword, its binder "), str_lit!("after it: `(abs #:t t type)`"))), n)? {}
                    } else {
                        match fail_at(mxp, maker_st, mx_fail, string_append(str_lit!("a template's `val` writes its label "), str_lit!("as a keyword: `(val #:x type)`")), n)? {}
                    };
                    if (given && not(binds)) {
                        with_core(mxp, maker_st, kid(p, int_lit(1)), s_label());
                        with_kids(mxp, maker_st, kid(p, int_lit(1)), k_pvar(syn_symbol(mxp, maker_st, n)?))
                    } else {
                        ()
                    };
                    if string_eq_p(word, str_lit!("abs")) {
                        ()
                    } else {
                        desc_each_scoped(mxp, maker_st, mx_fail, ps, if apart {
                            cdr(cdr(cdr(p)))
                        } else {
                            cdr(cdr(p))
                        }, if apart {
                            cdr(cdr(cdr(parts)))
                        } else {
                            cdr(cdr(parts))
                        }, r#as)?
                    };
                    (ks, ms, r#as) = (cdr(ks), cdr(ms), if apart {
                        append(r#as, the::<Atms>(kayak_rt::cons(desc_binder(mxp, maker_st, mx_fail, ps, kid(p, int_lit(2)), nth(parts, int_lit(2)))?, kayak_rt::nil())))
                    } else if (binds && syn_symbol_p(n)) {
                        append(r#as, the::<Atms>(kayak_rt::cons(desc_binder(mxp, maker_st, mx_fail, ps, kid(p, int_lit(1)), n)?, kayak_rt::nil())))
                    } else {
                        r#as
                    });
                    continue;
                }
            }
        }
    }

