    pub fn letters_from_p(mut n: Str, mut i: Int) -> bool {
        loop {
            if _eq(i, string_length(n)) {
                return true;
            } else {
                if (char_eq_p(string_ref(n, i), 'A') || char_eq_p(string_ref(n, i), 'D')) {
                    i = _plus(i, int_lit(1));
                    continue;
                } else {
                    return false;
                }
            }
        }
    }

