    pub fn root_rings<'mxp, Place_Mxp: kayak_rt::Visit>(mut mxp: &'mxp Place_Mxp, mut maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mut root: Int, mut mi: Int, mut of: MxInferInts, mut ps: ByClause, mut cid: Int) -> SiteRings {
        loop {
            if null_p(ps) {
                return nil::<Product_11_12<Int, List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Rd>>>>();
            } else if (null_p(car(ps)) || not(_eq(car(of), mi)) || null_p(car(car(ps)).1)) {
                (of, ps, cid) = (cdr(of), cdr(ps), _plus(cid, int_lit(1)));
                continue;
            } else {
                let e = car(car(car(ps)).1);
                let ribs = if null_p(e.0) {
                    nil::<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Lv>>()
                } else {
                    let l = lvs_of(mxp, maker_st, cid, the::<MxEnvTypesLevels>(kayak_rt::cons(lv_rib(e.0), kayak_rt::nil())));
                    if (not(null_p(l)) && not(null_p(car(l)))) {
                        kayak_rt::cons(car(car(l)), kayak_rt::nil())
                    } else {
                        nil::<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Lv>>()
                    }
                };
                let cages = cage_lvs(ints_sorted(cage_parts(mxp, maker_st, cid, e.1), nil::<Int>()));
                let rs = mx_solve_rings_of(mxp, maker_st, append(ribs, cages), root, cid);
                let rest = root_rings(mxp, maker_st, root, mi, cdr(of), cdr(ps), _plus(cid, int_lit(1)));
                if null_p(rs) {
                    return rest;
                } else {
                    return cons(Product_11_12(cid, car(rs)), rest);
                }
            }
        }
    }

