    pub fn expand_procedural<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, name: Symbol, s: kayak_rt::data::DataAt<'static, Syn>, made: Int) -> Result<kayak_rt::data::DataAt<'static, Syn>, Unwind> {
        let p = car(procedural_of(mxp, maker_st, name));
        let style = p.0;
        let a = syn_start(s);
        let b = syn_end(s);
        let in_use = kayak_rt::closure1((mx_fail, name, a, b,), |(mx_fail, name, a, b,), m: Str| {
            Ok(match mx_fail.call(string_append(str_lit!("a use of `"), string_append(symbol_to_string(name), string_append(str_lit!("`: "), m))), a, b)? {})
        });
        let opened = kayak_rt::closure1((mxp, maker_st, mx_fail, made, p, style,), |(mxp, maker_st, mx_fail, made, p, style,), at: kayak_rt::data::DataAt<'static, Syn>| {
            Ok(keywords(mxp, maker_st, mx_fail, file_macros(mxp, maker_st, if _eq(style, int_lit(1)) {
                closed(mxp, maker_st, mx_fail, at, true, made)?
            } else if _eq(style, int_lit(2)) {
                closed(mxp, maker_st, mx_fail, at, false, made)?
            } else {
                tagged(mxp, maker_st, at, made)
            }, p.2.3, made))?)
        });
        let tagcase_ = mx_call_procedural(style, p.1, syn_to_datum(s), mx_fresh_tag_of(mxp, maker_st, made), p.4);
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("ok") } {
            let d: kayak_rt::value::Value = kayak_rt::sum_payload::<kayak_rt::value::Value>(tagcase_);
            Ok(opened.call(syn_of_datum(d, new_source_key(mxp, maker_st, a, made), new_source_key(mxp, maker_st, b, made), made))?)
        } else if tag_ == const { kayak_rt::tag_hash("failed") } {
            let why: Str = kayak_rt::sum_payload::<Str>(tagcase_);
            match in_use.call(string_append(str_lit!("its transformer: "), why))? {};
            Ok(s)
        } else if tag_ == const { kayak_rt::tag_hash("apart") } {
            let u: () = kayak_rt::sum_payload::<()>(tagcase_);
            let tagcase_ = mx_procedural_run(mxp, maker_st, applied_text(style, p.1, syn_text(s), made, p.4));
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("failed") } {
                let why: Str = kayak_rt::sum_payload::<Str>(tagcase_);
                match in_use.call(string_append(str_lit!("its transformer: "), why))? {};
                Ok(s)
            } else if tag_ == const { kayak_rt::tag_hash("ok") } {
                let out: Str = kayak_rt::sum_payload::<Str>(tagcase_);
                let read = read_answer(out, new_source_key(mxp, maker_st, a, made), new_source_key(mxp, maker_st, b, made), made);
                if null_p(read) {
                    match in_use.call(string_append(str_lit!("its transformer gave `"), string_append(out, str_lit!("`, not one form"))))? {};
                    Ok(s)
                } else {
                    Ok(opened.call(car(read))?)
                }
            } else { unreachable!() }
        } else { unreachable!() }
    }

    pub fn procedural_expanded<'mxp, Place_Mxp: kayak_rt::Visit>(mxp: &'mxp Place_Mxp, maker_st: &'mxp MadeLoad1ExpandFaceState<'mxp, Place_Mxp>, mx_fail: kayak_rt::Proc3<'mxp, Str, Int, Int, Result<Void, Unwind>>, name: Symbol, s: kayak_rt::data::DataAt<'static, Syn>, made: Int) -> Result<kayak_rt::data::DataAt<'static, Syn>, Unwind> {
        let shown = string_append(str_lit!("a use of `"), string_append(symbol_to_string(name), str_lit!("`: ")));
        let in_use = kayak_rt::closure3((mx_fail, shown,), |(mx_fail, shown,), m: Str, a: Int, b: Int| {
            Ok(match mx_fail.call(string_append(shown, m), a, b)? {})
        });
        let at_use = kayak_rt::closure3((mx_fail, s, shown,), |(mx_fail, s, shown,), m: Str, a: Int, b: Int| {
            Ok(match mx_fail.call(string_append(shown, m), syn_start(s), syn_end(s))? {})
        });
        let m = car(macro_of_defined(name, get(maker_st.defined.get().unwrap())));
        let sig = m.0;
        let defn = _eq(m.3, int_lit(1));
        let contract = car(procedural_of(mxp, maker_st, name)).3;
        let operands = nth(split(s), int_lit(1));
        if not(contract) {
            Ok(expand_procedural(mxp, maker_st, mx_fail, name, s, made)?)
        } else {
            nodes_reset_x(mxp, maker_st);
            align(mxp, maker_st, in_use, int_lit(2), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Sty>, List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::MxEnvTypesLevel>>, bool, List<Product_11_12<List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Syn>>, List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Syn>>>>, Int>>>()), sig, operands, int_lit(-1), nil::<bool>())?;
            let out = expand_procedural(mxp, maker_st, mx_fail, name, s, made)?;
            if _eq(get(maker_st.mx_procedural_contracts.get().unwrap()), int_lit(0)) {
                Ok(out)
            } else {
                let held = if defn {
                    defined_held(mxp, maker_st, at_use, sig, operands, out, made)?;
                    nodes_reset_x(mxp, maker_st);
                    align(mxp, maker_st, in_use, int_lit(2), the::<Pvars>(nil::<Product_11_12<Symbol, Product_11_12_13_14_15<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Sty>, List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::MxEnvTypesLevel>>, bool, List<Product_11_12<List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Syn>>, List<kayak_rt::data::DataAt<'static, made__load__0__expander_kc::Syn>>>>, Int>>>()), sig, operands, int_lit(-1), nil::<bool>())?
                } else {
                    int_lit(0)
                };
                let r = contract_renames(mxp, maker_st, in_use, sig, operands)?;
                let fresh = r.1;
                if null_p(fresh) {
                    Ok(out)
                } else {
                    let out2 = expand_procedural(mxp, maker_st, mx_fail, name, renamed_use(mxp, maker_st, in_use, s, r.0)?, made)?;
                    contract_held(mxp, maker_st, in_use, s, out, out2, fresh, made, if defn {
                        s_defn()
                    } else {
                        s_expr()
                    })?;
                    Ok(out)
                }
            }
        }
    }

